// Apply imported SOA timers when update_soa=true on the import
// payload. mname/rname strip the trailing dot + take only the
// left-most label (matches Python's _ImportPayload behavior).
func (q *Queries) UpdateDnsZoneSoa(ctx context.Context, arg UpdateDnsZoneSoaParams) error {
	_, err := q.db.Exec(ctx, updateDnsZoneSoa,
		arg.ID,
		arg.SoaMname,
		arg.SoaRname,
		arg.SoaRefresh,
		arg.SoaRetry,
		arg.SoaExpire,
		arg.SoaMinimum,
		arg.DefaultTTL,
	)
	return err
}
